//
// Exports:
//   nextRange(prefix, count) -> Promise<{ start, end }>
//
// Safety model:
//   - Mutual exclusion via an exclusive lock directory (mkdir is atomic on POSIX).
//   - Contenders retry with randomized exponential-ish backoff.
//   - Stale locks (mtime older than STALE_MS) are taken over by atomically
//     renaming them away (only one contender can win the rename race).
//   - State updates are atomic: write temp file + rename.

import { promises as fs } from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import os from 'node:os';

/** A lock older than this is considered abandoned. */
export const STALE_LOCK_MS = 2000;
/** Give up entirely after this long waiting for the lock. */
export const LOCK_TIMEOUT_MS = 120_000;

const __dirname = path.dirname(fileURLToPath(import.meta.url));

function stateDir() {
  return process.env.BATES_STATE_DIR || path.join(os.tmpdir(), 'bates-default');
}

function stateFile() {
  return path.join(stateDir(), 'state.json');
}

function lockDir() {
  return stateFile() + '.lock';
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function readState() {
  let raw;
  try {
    raw = await fs.readFile(stateFile(), 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }
  const state = JSON.parse(raw);
  if (typeof state !== 'object' || state === null) {
    throw new Error(`corrupt state file: ${stateFile()}`);
  }
  return state;
}

async function writeState(state) {
  const tmp = `${stateFile()}.${process.pid}.${crypto.randomUUID()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(state, null, 2));
  await fs.rename(tmp, stateFile()); // atomic on POSIX
}

/**
 * Try once to steal a stale lock. Returns true if this process removed one.
 * Uses rename() so that at most one contender wins the takeover race.
 */
async function tryStealStaleLock() {
  let st;
  try {
    st = await fs.stat(lockDir());
  } catch {
    return false; // gone already; someone else handled it
  }
  if (Date.now() - st.mtimeMs < STALE_LOCK_MS) return false;

  const trash = `${lockDir()}.stale-${process.pid}-${crypto.randomUUID()}`;
  try {
    await fs.rename(lockDir(), trash); // atomic: single winner
  } catch {
    return false; // lost the race or lock vanished; just retry normally
  }
  await fs.rm(trash, { recursive: true, force: true });
  return true;
}

async function withLock(fn) {
  const deadline = Date.now() + LOCK_TIMEOUT_MS;
  let attempt = 0;
  for (;;) {
    try {
      await fs.mkdir(lockDir()); // exclusive acquisition
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
      await tryStealStaleLock();
      if (Date.now() > deadline) {
        throw new Error(`timed out acquiring Bates lock at ${lockDir()}`);
      }
      // randomized backoff: 2ms .. 2^(attempt+1) ms, capped at 50ms
      const cap = Math.min(50, 2 ** Math.min(attempt + 1, 8));
      await sleep(Math.floor(2 + Math.random() * cap));
      attempt++;
      continue;
    }
    try {
      return await fn();
    } finally {
      await fs.rm(lockDir(), { recursive: true, force: true });
    }
  }
}

/**
 * Reserve `count` contiguous numbers for `prefix`.
 * Returns { start, end } inclusive; numbers are gap-free per prefix across
 * all concurrent callers.
 */
export async function nextRange(prefix, count) {
  if (!Number.isInteger(count) || count < 1) {
    throw new Error(`count must be a positive integer, got ${count}`);
  }
  if (typeof prefix !== 'string' || prefix.length === 0) {
    throw new Error('prefix must be a non-empty string');
  }
  return withLock(async () => {
    await fs.mkdir(stateDir(), { recursive: true });
    const state = await readState();
    const last = state[prefix] ?? 0;
    const start = last + 1;
    const end = last + count;
    state[prefix] = end;
    await writeState(state);
    return { start, end };
  });
}

/** Read the current high-water mark for a prefix (for diagnostics/tests). */
export async function peek(prefix) {
  const state = await readState().catch(() => ({}));
  return state[prefix] ?? 0;
}
"})
