result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/stamp.mjs", "content": "// Bates stamper — stamps text files page-by-page.
//
// Pages are separated by form feeds (\f). Each page gets a footer line
// "PREFIX-{n}" where n is zero-padded to 7 digits, numbered sequentially
// across the whole document using the counter service.

import { promises as fs } from 'node:fs';
import { nextRange } from './counter.mjs';
import { fileURLToPath } from 'node:url';

const PAD_WIDTH = 7;

/** Zero-padded number, e.g. formatNumber(42) -> "0000042". */
export function formatNumber(n) {
  return String(n).padStart(PAD_WIDTH, '0');
}

/** Footer line for a page, e.g. footer("ACME", 42) -> "ACME-0000042". */
export function footer(prefix, n) {
  return `${prefix}-${formatNumber(n)}`;
}

/**
 * Stamp `text` starting at `firstNumber`. Pages split on \f; each page gets
 * a footer line appended. Returns { text, pages } where pages is how many
 * numbers were consumed.
 */
export function stampText(text, prefix, firstNumber) {
  const parts = text.split('\f');
  let n = firstNumber;
  const stamped = parts.map((page) => {
    const body = page.replace(/\n+$/, '');
    return `${body}\n${footer(prefix, n++)}`;
  });
  return { text: stamped.join('\f'), pages: parts.length };
}

/**
 * Stamp a file in place (or to `outputPath` if given), reserving exactly as
 * many numbers as the document has pages under `prefix`.
 */
export async function stampFile(filePath, prefix, outputPath = filePath) {
  const original = await fs.readFile(filePath, 'utf8');
  const pageCount = original.split('\f').length;
  const { start } = await nextRange(prefix, pageCount);
  const { text } = stampText(original, prefix, start);
  await fs.writeFile(outputPath, text);
  return { first: start, last: start + pageCount - 1 };
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const [, , file, prefix] = process.argv;
  if (!file || !prefix) {
    console.error('usage: node stamp.mjs <file> <prefix>');
    process.exit(1);
  }
  const { first, last } = await stampFile(file, prefix);
  console.log(`stamped ${file}: ${prefix} ${first}..${last}`);
}
"})
