import assert from 'node:assert/strict';
import { promises as fs } from 'node:fs';
import { spawn } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import os from 'node:os';
import { nextRange, peek } from '../counter.mjs';
import { formatNumber, footer, stampText } from '../stamp.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WORKER = path.join(__dirname, 'worker.mjs');

let tmp;

beforeEach(async () => {
  tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'bates-test-'));
  process.env.BATES_STATE_DIR = tmp;
});

afterEach(async () => {
  delete process.env.BATES_STATE_DIR;
  await fs.rm(tmp, { recursive: true, force: true });
});

// ---------------------------------------------------------------- padding

test('formatNumber zero-pads to 7 digits', () => {
  assert.equal(formatNumber(1), '0000001');
  assert.equal(formatNumber(42), '0000042');
  assert.equal(formatNumber(999999), '0999999');
  assert.equal(formatNumber(12345678), '12345678'); // over-width: no truncation
});

test('footer renders PREFIX-{n} zero-padded', () => {
  assert.equal(footer('ACME', 5), 'ACME-0000005');
  assert.equal(footer('X', 1234567), 'X-1234567');
});

test('nextRange returns contiguous inclusive ranges', async () => {
  const a = await nextRange('P', 3);
  const b = await nextRange('P', 2);
  assert.deepEqual([a.start, a.end], [1, 3]);
  assert.deepEqual([b.start, b.end], [4, 5]);
  assert.equal(await peek('P'), 5);
});

// --------------------------------------------------------- multi-page stamping

test('stampText stamps every page split on \\f with sequential numbers', () => {
  const doc = 'page one\fpage two\fpage three';
  const { text, pages } = stampText(doc, 'DOC', 10);

  assert.equal(pages, 3);
  const pagesOut = text.split('\f');
  assert.equal(pagesOut.length, 3);

  assert.match(pagesOut[0], /^page one\nDOC-0000010$/);
  assert.match(pagesOut[1], /^page two\nDOC-0000011$/);
  assert.match(pagesOut[2], /^page three\nDOC-0000012$/);
});

test('stampText consumes exactly one number per page', async () => {
  await fs.writeFile(path.join(tmp, 'doc.txt'), 'a\f\b\fc');
  // stampFile is exercised via counter reservation semantics:
  const before = await peek('MULTI');
  const r1 = stampText('x\fy\fz', 'MULTI', before + 1);
  assert.deepEqual(
    r1.text.split('\f').map((p) => p.split('\n').pop()),
    ['MULTI-0000001', 'MULTI-0000002', 'MULTI-0000003']
  );
  const after = await nextRange('MULTI', 1); // continues where stamping left off
  assert.equal(after.start, 4);
});

// ---------------------------------------------------------- stale-lock recovery

test('stale lock (old mtime) is taken over', async () => {
  await fs.mkdir(path.join(tmp, 'state.json.lock'));
  // Backdate the lock dir so it looks abandoned (> 2s old).
  const old = new Date(Date.now() - 5000);
  await fs.utimes(path.join(tmp, 'state.json.lock'), old, old);

  const range = await nextRange('STALE', 5);
  assert.deepEqual(range, { start: 1, end: 5 }); // did not hang or fail
  assert.equal(await peek('STALE'), 5);

  // Lock dir must be gone afterwards so future acquisitions work immediately.
  await assert.rejects(fs.stat(path.join(tmp, 'state.json.lock')), /ENOENT/);
});

test('fresh lock (< 2s) is respected until released', async () => {
  const lockPath = path.join(tmp, 'state.json.lock');
  await fs.mkdir(lockPath);
  const t0 = Date.now();

  // Hold the lock ourselves for ~300ms, then release; nextRange must wait,
  // not steal (lock is fresh).
  setTimeout(() => fs.rm(lockPath, { recursive: true, force: true }), 300);
  const range = await nextRange('FRESH', 1);
  assert.ok(Date.now() - t0 >= 250, 'should have waited for the fresh lock');
  assert.deepEqual(range, { start: 1, end: 1 });
});

// ------------------------------------------------------------- concurrency

function runWorker(prefix, count) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [WORKER, prefix, String(count)], {
      env: { ...process.env, BATES_STATE_DIR: tmp },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => (out += d));
    child.stderr.on('data', (d) => (err += d));
    child.on('close', (code) => {
      if (code !== 0) reject(new Error(`worker exited ${code}: ${err}`));
      else resolve(JSON.parse(out.trim()));
    });
    child.on('error', reject);
  });
}

test('8 concurrent workers x 50 pages => 400 unique, gap-free numbers', { timeout: 60_000 }, async () => {
  const WORKERS = 8;
  const PAGES = 50;
  const ranges = await Promise.all(
    Array.from({ length: WORKERS }, () => runWorker('CONC', PAGES))
  );

  const issued = [];
  for (const r of ranges) {
    assert.ok(r.end - r.start + 1 === PAGES, `range size ${r.end - r.start + 1}`);
    for (let n = r.start; n <= r.end; n++) issued.push(n);
  }

  // Unique
  assert.equal(new Set(issued).size, WORKERS * PAGES, 'numbers must be unique');

  // Contiguous from 1 and gap-free
  issued.sort((a, b) => a - b);
  assert.equal(issued[0], 1, 'first number must be 1');
  assert.equal(issued.at(-1), WORKERS * PAGES, `last number must be ${WORKERS * PAGES}`);
  for (let i = 0; i < issued.length; i++) {
    assert.equal(issued[i], i + 1, `gap at index ${i}: got ${issued[i]}, expected ${i + 1}`);
  }

  assert.equal(await peek('CONC'), WORKERS * PAGES);
});
"})
